import{_ as e,b as t,c as l,d as r}from"./chunks/framework.D4cM_aKq.js";const p=JSON.parse('{"title":"RAG：先找到资料，再组织答案","description":"从检索、上下文到生成，理解知识问答系统的基本组成与边界。","frontmatter":{"layout":"article","title":"RAG：先找到资料，再组织答案","description":"从检索、上下文到生成，理解知识问答系统的基本组成与边界。","date":"2026-10-16","category":"人工智能","directory":"基础概念","tags":["RAG","知识管理","学习笔记"],"featured":true,"sample":true},"headers":[{"level":2,"title":"一个直观的理解","slug":"一个直观的理解","link":"#一个直观的理解","children":[]},{"level":2,"title":"基本流程","slug":"基本流程","link":"#基本流程","children":[{"level":3,"title":"整理与切分","slug":"整理与切分","link":"#整理与切分","children":[]},{"level":3,"title":"检索候选内容","slug":"检索候选内容","link":"#检索候选内容","children":[]},{"level":3,"title":"根据资料生成","slug":"根据资料生成","link":"#根据资料生成","children":[]}]},{"level":2,"title":"怎样判断效果","slug":"怎样判断效果","link":"#怎样判断效果","children":[]},{"level":2,"title":"适用边界","slug":"适用边界","link":"#适用边界","children":[]},{"level":2,"title":"相关项目","slug":"相关项目","link":"#相关项目","children":[]}],"relativePath":"journal/ai/rag-basics.md","filePath":"journal/ai/rag-basics.md"}'),i={name:"journal/ai/rag-basics.md"};function d(n,a,o,h,s,c){return t(),l("div",null,[...a[0]||(a[0]=[r('<h2 id="一个直观的理解" tabindex="-1">一个直观的理解 <a class="header-anchor" href="#一个直观的理解" aria-label="Permalink to &quot;一个直观的理解&quot;">​</a></h2><p>检索增强生成可以理解为：先在资料中找到与问题相关的内容，再把这些资料和问题一起交给模型组织回答。</p><p>它把“找到证据”和“表达答案”拆成两个环节，也让答案有机会带上可追溯的出处。</p><h2 id="基本流程" tabindex="-1">基本流程 <a class="header-anchor" href="#基本流程" aria-label="Permalink to &quot;基本流程&quot;">​</a></h2><h3 id="整理与切分" tabindex="-1">整理与切分 <a class="header-anchor" href="#整理与切分" aria-label="Permalink to &quot;整理与切分&quot;">​</a></h3><p>将文档拆分为适合检索的片段，同时保留标题、原文路径与章节。片段过短可能缺少上下文，过长则容易夹带不相关的信息。</p><h3 id="检索候选内容" tabindex="-1">检索候选内容 <a class="header-anchor" href="#检索候选内容" aria-label="Permalink to &quot;检索候选内容&quot;">​</a></h3><p>关键词检索依靠文本匹配，向量检索利用语义相似度。实践中可以组合两者，再对候选结果重排。</p><h3 id="根据资料生成" tabindex="-1">根据资料生成 <a class="header-anchor" href="#根据资料生成" aria-label="Permalink to &quot;根据资料生成&quot;">​</a></h3><p>将相关片段放入上下文，要求模型依据这些资料回答，并标明引用。模型应能表达不确定性，而不是在缺少依据时编造内容。</p><h2 id="怎样判断效果" tabindex="-1">怎样判断效果 <a class="header-anchor" href="#怎样判断效果" aria-label="Permalink to &quot;怎样判断效果&quot;">​</a></h2><p>分别评估检索与生成：正确资料有没有被找出来，回答是否使用了这些资料，引用能否支持对应结论。</p><table tabindex="0"><thead><tr><th>层次</th><th>需要观察的问题</th></tr></thead><tbody><tr><td>检索</td><td>相关片段是否进入候选结果？</td></tr><tr><td>生成</td><td>回答是否忠于给定资料？</td></tr><tr><td>引用</td><td>来源是否真的支持结论？</td></tr></tbody></table><h2 id="适用边界" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界" aria-label="Permalink to &quot;适用边界&quot;">​</a></h2><p>接入文档并不意味着系统自动获得了可靠的推理能力。资料质量、权限控制、检索策略和评估方式都影响最终体验。</p><p>本篇是概念与排版示例。实际项目应结合具体模型、语料和评估集记录结论。</p><h2 id="相关项目" tabindex="-1">相关项目 <a class="header-anchor" href="#相关项目" aria-label="Permalink to &quot;相关项目&quot;">​</a></h2><p><a href="/projects/ai/knowledge-lab.html">拾知 · 知识检索实验</a> 展示了如何介绍同类实验项目。</p>',18)])])}const b=e(i,[["render",d]]);export{p as __pageData,b as default};
